insert into public.tasks (status, owner_id, due_date, trip_day, est_cost_thb, actual_cost_thb, booking_url, booking_ref, is_everyone, title, category, detail, id, sort_order, created_at, updated_at) values
('todo', null, null, '2026-11-02', null, null, null, null, false, 'Night of Mon 2 Nov has no hotel booked', 'urgent', 'Our three bookings cover Phuket 31 Oct to 2 Nov, Arawana Pattaya 3 to 6 Nov, and Marigold Sukhumvit 6 to 8 Nov. The itinerary left "optional overnight travel to Bangkok" undecided, so the night of Mon 2 Nov falls straight into the gap. Three options: (a) evening flight Phuket to Bangkok plus one night in a Bangkok hotel, which is cleanest; (b) an extra night in Phuket and fly out the morning of 3 Nov; (c) the overnight bus, 12 to 14 hours, not recommended for six people. Pick one this week — everything else on 2 and 3 Nov depends on it.', '10000000-0000-4000-8000-000000000001', 1, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, '2026-11-02', null, null, null, null, false, 'Phuket → Bangkok flight, 2 Nov, 6 seats', 'urgent', 'Thai AirAsia, Thai Lion, Nok Air and Thai Vietjet all fly this route. It''s only 1h25 to 1h40 in the air versus 12 to 14 hours by bus. Check this first: also price Phuket to U-Tapao, which is Pattaya''s own airport. If a flight works we skip Bangkok entirely on 2 and 3 Nov and save half a day plus the extra hotel night.', '10000000-0000-4000-8000-000000000002', 2, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, '2026-11-08', null, null, null, null, false, 'Confirm Marigold checkout date', 'urgent', 'The flight out is 9:50pm on Sunday 8 Nov. Did we book two nights (6th and 7th) or three (6th, 7th and 8th)? If only two, we need late checkout or luggage storage arranged for the 8th — otherwise six people are dragging shopping bags around Bangkok all afternoon.', '10000000-0000-4000-8000-000000000003', 3, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, '2026-11-01', 18000, null, null, null, false, 'Phi Phi + Maya Bay boat', 'booking', 'For six people, get a quote for a private speedboat against a small-group tour. Private often lands close on a per-head basis and we control the timing and beat the crowds. Maya Bay is open in November — the annual closure only runs 1 August to 30 September. Confirm whether the national park entry fee is included in the quote or charged separately on the day.', '10000000-0000-4000-8000-000000000004', 4, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, '2026-11-02', 9000, null, null, null, false, 'Mario Kart + shooting range, Phuket', 'booking', 'Confirm both venues can take a group of six and pre-book the time slots. Leave a buffer, because this is also a checkout and packing day.', '10000000-0000-4000-8000-000000000005', 5, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, '2026-11-03', 2500, null, null, null, false, 'Van: airport → Pattaya', 'booking', 'Six people plus luggage needs a proper van, not two taxis. Pre-book it. Negotiating with drivers at arrivals with six people and a luggage pile never goes well.', '10000000-0000-4000-8000-000000000006', 6, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, '2026-11-04', 3600, null, null, null, false, 'Sanctuary of Truth tickets', 'booking', 'Online tickets are cheaper than buying at the gate. It''s an active wood-carving restoration site, so confirm no work is blocking access on the day we''re going.', '10000000-0000-4000-8000-000000000007', 7, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, '2026-11-05', 6000, null, null, null, false, 'Koh Larn / Coral Island boat', 'booking', 'Speedboat plus beach transfer. Keep it cancellable — sea conditions decide this one. Don''t stack anything after the boat gets back.', '10000000-0000-4000-8000-000000000008', 8, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, '2026-11-06', 2800, null, null, null, false, 'Van: Pattaya → Bangkok', 'booking', 'Leave after a late breakfast, roughly 2 hours on the road. Getting in by early afternoon leaves time to rest before Wat Arun at sunset.', '10000000-0000-4000-8000-000000000009', 9, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, '2026-11-08', 1200, null, null, null, false, 'Van: hotel → Suvarnabhumi', 'booking', 'Leave between 6:00 and 6:30pm for the 9:50pm flight. Book for six people plus shopping bags — we''ll have considerably more luggage going home than we came with.', '10000000-0000-4000-8000-000000000010', 10, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, '2026-11-07', 10800, null, null, null, false, 'Muay Thai at Rajadamnern Stadium', 'optional', 'Saturday 7 Nov is the Rajadamnern World Series flagship card, the best night of the week. Book direct at rajadamnern.com — their official ticketing partner is Ticketmelon. Never buy from touts at the entrance, who quote inflated prices for bad seats. On seats: Club Class at 1,800 baht is the value pick with clear sightlines. Ringside at 2,500 baht is genuinely better if we''re only doing this once. Skip third class at 1,000 baht — you''re behind wire mesh with the gambling crowd and will barely see the fights. The stadium is in the old city near Khao San, not on the BTS, so budget 25 to 40 minutes by Grab from Sukhumvit. Conflict: 7 Nov already has Wat Sam Phran and Chinatown.', '10000000-0000-4000-8000-000000000011', 11, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, '2026-11-08', null, null, null, null, false, 'Chatuchak Weekend Market', 'optional', '15,000 stalls, and it runs Saturday and Sunday only — 8 Nov is a Sunday, so it fits. Go between 9 and 10am before the heat turns it miserable. Best place in the city for souvenirs, handicrafts and homeware.', '10000000-0000-4000-8000-000000000012', 12, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, null, null, null, null, null, false, 'Platinum Fashion Mall, Pratunam', 'optional', 'The genuinely cheap shopping option, as opposed to the outlets. Over 1,300 wholesale shops across six floors, open to anyone with no membership needed. Rates drop to wholesale once you buy three or more of the same item, so pool purchases across the group. Two practical notes: most shops have no trial rooms, so bring a measuring tape and know your sizes; and go on a weekday morning before noon or it''s a crush. Ten minutes on foot from either Ratchathewi or Chidlom BTS.', '10000000-0000-4000-8000-000000000013', 13, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, null, null, null, null, null, false, 'Siam Premium Outlets vs Central Village', 'optional', 'Siam Premium Outlets is the better of the two — it has both Nike and Adidas where Central Village only has Adidas, plus a stronger overall brand mix and far better food. Both sit near Suvarnabhumi, so the smart play is hitting one on the way to the airport rather than burning a half day from the city. There''s a shuttle from Siam Paragon at 150 baht each way. Set expectations: Thai outlet discounts are often modest, sometimes as low as 10%, and on sports brands you may find prices no better than a sale at home. Go for the hunt, not guaranteed savings.', '10000000-0000-4000-8000-000000000014', 14, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, '2026-10-28', null, null, null, null, null, true, 'TDAC — Thailand Digital Arrival Card', 'admin', 'Free, and legally required for every traveller entering Thailand including visa-free arrivals. Submit within 72 hours before landing on 31 Oct, via the official government portal only — lookalike sites charge fake fees. Airlines are required to check this at check-in, so no TDAC means denied boarding. This is the single most-forgotten item on any Thailand trip. Everyone post a screenshot in the group when yours is done.', '10000000-0000-4000-8000-000000000015', 15, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, null, null, null, null, null, true, 'Passport valid 6+ months', 'admin', 'Indian passports get visa-free entry to Thailand, so there''s no visa application to make. But check every passport has at least six months of validity beyond 8 November 2026, and a couple of blank pages.', '10000000-0000-4000-8000-000000000016', 16, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, null, 6000, null, null, null, true, 'Travel insurance', 'admin', 'Two boat days and a shooting range on this itinerary — worth having. Check whether a single group policy is cheaper than six individual ones.', '10000000-0000-4000-8000-000000000017', 17, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, null, null, null, null, null, true, 'Print return ticket + all 3 hotel confirmations', 'admin', 'Thai immigration occasionally asks arriving tourists for proof of onward travel and accommodation. A printout each avoids a bad twenty minutes at the counter.', '10000000-0000-4000-8000-000000000018', 18, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, null, null, null, null, null, false, 'Forex — THB cash + low-markup card', 'admin', 'Airport exchange rates are the worst available anywhere. Carry some baht from India, then top up at SuperRich or Vasu in Bangkok for the best rates in the city. Bring a card with low forex markup as backup.', '10000000-0000-4000-8000-000000000019', 19, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, null, null, null, null, null, true, 'eSIM or local SIM', 'admin', 'AIS and TrueMove counters are in Phuket arrivals, or buy an eSIM before flying so you land already connected. At least three of the six should have working data at any time.', '10000000-0000-4000-8000-000000000020', 20, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, null, null, null, null, null, true, 'Install Grab + download offline maps', 'admin', 'Grab is the taxi app across Thailand — metered, no haggling, no language problem. Download offline Google Maps for Phuket, Pattaya and Bangkok before we fly.', '10000000-0000-4000-8000-000000000021', 21, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z'),
('todo', null, null, null, null, null, null, null, false, 'Shared folder: passport scans + all bookings', 'admin', 'One cloud folder everyone can reach, holding passport scans, flight PNRs, hotel confirmations and tour vouchers. Saves the trip if a phone dies or a bag walks off. Keep this in a PRIVATE folder, not in this app.', '10000000-0000-4000-8000-000000000022', 22, '2026-09-23T00:00:00.000Z', '2026-09-23T00:00:00.000Z')
insert into public.itinerary_days (conflict_note, day_date, city, hotel, title, notes, watch_out, id, created_at) values
(null, '2026-10-31', 'Phuket', 'Memory Boutique, Patong', 'Phuket arrival', 'Depart Bengaluru 10:35am, land Phuket 3:50pm. Check in, then Old Phuket Town for an evening walk, food and cafes.', 'Don''t add a major excursion after a travel day.', '20000000-0000-4000-8000-000000000001', '2026-09-23T00:00:00.000Z'),
(null, '2026-11-01', 'Phuket', 'Memory Boutique, Patong', 'Phi Phi Islands + Maya Bay', 'Full-day boat excursion. Snorkelling and swimming if sea conditions allow. Back to Phuket for a relaxed dinner.', 'Don''t stack anything after the boat returns. Everyone will be wrecked and sunburnt.', '20000000-0000-4000-8000-000000000002', '2026-09-23T00:00:00.000Z'),
('No hotel booked for tonight, and it''s also a checkout and activity day. Resolve the accommodation before booking activities.', '2026-11-02', 'Phuket → ?', 'NOT BOOKED', 'Phuket activities, then travel', 'Morning and afternoon for Mario Kart and the shooting activity. Keep a buffer for packing and checkout. Fly out in the evening.', 'This night has no hotel booked. It''s the biggest open question in the whole plan.', '20000000-0000-4000-8000-000000000003', '2026-09-23T00:00:00.000Z'),
(null, '2026-11-03', 'Pattaya', 'Arawana', 'Transfer to Pattaya', 'Arrive, transfer to Pattaya, check in, rest, lunch. Walking Street in the evening if the whole group is comfortable with it.', 'This is a transition and recovery day. Don''t overload it.', '20000000-0000-4000-8000-000000000004', '2026-09-23T00:00:00.000Z'),
(null, '2026-11-04', 'Pattaya', 'Arawana', 'Sanctuary of Truth', 'Morning at the Sanctuary of Truth. Afternoon for massage, pool and relaxation. Optional viewpoint or cafe if anyone still has energy.', 'Keep the evening deliberately empty.', '20000000-0000-4000-8000-000000000005', '2026-09-23T00:00:00.000Z'),
(null, '2026-11-05', 'Pattaya', 'Arawana', 'Coral Island (Koh Larn)', 'Full or half day on Koh Larn. Beach and water activities. Relaxed final Pattaya evening.', 'Entirely weather and sea-condition dependent. Have a plan B.', '20000000-0000-4000-8000-000000000006', '2026-09-23T00:00:00.000Z'),
(null, '2026-11-06', 'Bangkok', 'Marigold Sukhumvit', 'Transfer to Bangkok, Wat Arun at sunset', 'Leave Pattaya after breakfast, roughly 2 hours. Check in and rest. Wat Arun around sunset, dinner after.', 'Arrive at Wat Arun by Chao Phraya river boat rather than by road. Much better approach, and sunset not midday.', '20000000-0000-4000-8000-000000000007', '2026-09-23T00:00:00.000Z'),
('Three competing plans on one day — Wat Sam Phran (3 hours of travel), Chinatown, and the Rajadamnern fight night. Pick two.', '2026-11-07', 'Bangkok', 'Marigold Sukhumvit', 'Wat Sam Phran + Chinatown — the heaviest day', 'Wat Sam Phran (the Dragon Temple) in the morning. It''s in Nakhon Pathom, outside central Bangkok, roughly 1.5 hours each way. Saturday hours are 6am to 6pm; weekdays are 9am to 5pm. Confirm close to the date because local hours change. Evening in Chinatown / Yaowarat for food.', 'This day is overloaded. It''s also Rajadamnern''s flagship fight night. Pick two of the three — temple, Chinatown, Muay Thai — don''t attempt all three. If the group is flagging, drop the temple rather than sacrificing Bangkok downtime for one photo.', '20000000-0000-4000-8000-000000000008', '2026-09-23T00:00:00.000Z'),
('Flight day. Shopping plus a 6:30pm airport departure is tight. Outlet near the airport only.', '2026-11-08', 'Bangkok → home', 'Checkout day', 'Shopping, then 9:50pm flight home', 'Morning and early afternoon for shopping. Leave for Suvarnabhumi around 6:00–6:30pm. Flight departs 9:50pm, lands Bengaluru 12:00am.', 'Siam Premium Outlets is near Suvarnabhumi, so shop there and go straight to the airport. A central Bangkok mall is NOT an outlet, and going there means crossing the city twice on a flight day. It''s a Sunday, so Chatuchak is also open — 9 to 10am before the heat.', '20000000-0000-4000-8000-000000000009', '2026-09-23T00:00:00.000Z')
